o esc_html($rh['level_number'].' — '.ucwords(str_replace('_',' ',$rh['level'])));?></td><td style="padding:8px"><?php echo esc_html(mysql2date(get_option('date_format'),$rh['joined']));?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p>No verified member joins through your tracker yet. Share your Smart QR or personal link to start building your network.</p><?php endif;?></article><?php if($identity['level_number']>=5):$amb=LMH_Backend::ambassador_tools($user->ID);?><article class="lmh-card"><h3>Physical Membership Card</h3><p>Eligible from Level 5 — Ambassador.</p><p>Status: <strong><?php echo esc_html(strtoupper(str_replace('_',' ',$amb['card']['status'])));?></strong></p><small>MEMBERSHIP CARD — NOT A PAYMENT CARD</small></article><?php else:?><article class="lmh-card"><h3>Keep Growing</h3><p>Your Smart QR and tracker are active now. Physical membership-card eligibility begins at Level 5 — Ambassador.</p></article><?php endif;?></div></section><?php $partners=LMH_Backend::partners();$eligible_partners=[];foreach($partners as $pid=>$pt){if(($pt['status']??'')==='active'&&in_array((int)$identity['level_number'],array_map('intval',(array)($pt['levels']??[])),true))$eligible_partners[$pid]=$pt;}?><section class="lmh-dashboard" id="partner-marketplace"><div class="lmh-kicker">Member Privileges</div><h2>Partner Marketplace</h2><p>Explore active Le Manager partner offers available to your Level <?php echo esc_html($identity['level_number']);?> membership.</p><?php if($eligible_partners):?><div class="lmh-partner-grid"><?php foreach($eligible_partners as $pt):?><article class="lmh-partner-card"><div class="lmh-partner-top"><span><?php echo esc_html($pt['category']?:'Le Manager Partner');?></span><strong>LEVEL <?php echo esc_html($identity['level_number']);?> ELIGIBLE</strong></div><h3><?php echo esc_html($pt['name']);?></h3><?php if(!empty($pt['location'])):?><p class="lmh-partner-location"><?php echo esc_html($pt['location']);?></p><?php endif;?><div class="lmh-partner-offer"><?php echo nl2br(esc_html($pt['offer']));?></div><div class="lmh-partner-actions"><?php if(!empty($pt['website'])):?><a class="lmh-btn" href="<?php echo esc_url($pt['website']);?>" target="_blank" rel="noopener">VISIT PARTNER</a><?php endif;?><a class="lmh-text-link" href="<?php echo esc_url(LMH_Backend::verification_url($user->ID));?>" target="_blank" rel="noopener">VERIFY MY MEMBERSHIP →</a></div></article><?php endforeach;?></div><?php else:?><div class="lmh-empty-state"><strong>More member privileges are coming.</strong><p>There are no active partner offers configured for your current level yet.</p></div><?php endif;?></section><?php endif;?><p><?php echo esc_html('LM '.(get_user_meta($user->ID,'lmh_fan_level',true)?:'Fan'));?> · <a href="<?php echo esc_url(get_edit_profile_url());?>">Edit account</a> · <a href="<?php echo esc_url(wp_logout_url(home_url('/')));?>">Sign out</a></p><section id="squad" class="lmh-squad"><h2>Le Manager Event Squad</h2><p>Stay part of the community that shows up for music.</p><button class="lmh-btn" id="squad-button" data-joined="<?php echo get_user_meta($user->ID,'lmh_event_squad',true)==='joined'?'true':'false';?>"><?php echo get_user_meta($user->ID,'lmh_event_squad',true)==='joined'?'LEAVE EVENT SQUAD':'JOIN EVENT SQUAD';?></button><p id="squad-status" role="status"></p></section><h2>Artists you follow</h2><div class="lmh-grid"><?php $ids=array_filter(array_map('intval',(array)get_user_meta($user->ID,'lmh_following',true)));$shown=0;foreach($ids as $id)if(get_post_status($id)==='publish'&&get_post_type($id)==='lmh_artist'){$shown++;echo '<a class="lmh-card" href="'.esc_url(get_permalink($id)).'">'.esc_html(get_the_title($id)).'</a>';}if(!$shown)echo '<p>Discover an artist and select Follow to add them here.</p>';?></div><p><a href="<?php echo esc_url(lmh_url('directory'));?>">Discover artists →</a></p><section class="lmh-profile-builder" id="professional-center">
